do $$
declare author uuid; voter uuid; judge uuid; campaign uuid; next_campaign uuid; poem uuid; second_poem uuid; rid uuid:=gen_random_uuid(); w public.la_poem_words; rejected boolean; current_week uuid;
begin
 select * into strict w from public.la_poem_words order by id limit 1;
 insert into public.la_users(primary_user_key) values('fp_qa_'||gen_random_uuid()) returning id into author;
 insert into public.la_users(primary_user_key) values('fp_qa_'||gen_random_uuid()) returning id into voter;
 insert into public.la_users(primary_user_key) values('fp_qa_'||gen_random_uuid()) returning id into judge;
 insert into public.la_poem_campaigns(word_id,word,starts_at,writing_ends_at,voting_ends_at) values(w.id,w.word,clock_timestamp()-interval '1 hour',clock_timestamp()+interval '1 hour',clock_timestamp()+interval '2 hours') returning id into campaign;
 poem:=public.la_submit_poem(author,campaign,'검증',array[substring(w.word,1,1)||'첫째',substring(w.word,2,1)||'둘째',substring(w.word,3,1)||'셋째'],rid);
 assert public.la_submit_poem(author,campaign,'검증',array['bad','bad','bad'],rid)=poem,'same request returns same poem';
 rejected:=false;
 begin perform public.la_submit_poem(author,campaign,'검증',array[substring(w.word,1,1)||'첫째',substring(w.word,2,1)||'둘째',substring(w.word,3,1)||'셋째'],gen_random_uuid()); exception when others then rejected:=sqlerrm like '%ALREADY_PARTICIPATED%'; end;
 assert rejected,'one entry per user per week';
 update public.la_poems set status='deleted' where id=poem;
 rejected:=false;
 begin perform public.la_submit_poem(author,campaign,'검증',array[substring(w.word,1,1)||'첫째',substring(w.word,2,1)||'둘째',substring(w.word,3,1)||'셋째'],gen_random_uuid()); exception when others then rejected:=sqlerrm like '%ALREADY_PARTICIPATED%'; end;
 assert rejected,'deleting does not reset participation';
 update public.la_poems set status='visible' where id=poem;
 second_poem:=public.la_submit_poem(voter,campaign,'검증',array[substring(w.word,1,1)||'첫째',substring(w.word,2,1)||'둘째',substring(w.word,3,1)||'셋째'],gen_random_uuid());
 rejected:=false;
 begin perform public.la_set_poem_reaction(author,poem,'funny'); exception when others then rejected:=sqlerrm like '%SELF_REACTION_NOT_ALLOWED%'; end;
 assert rejected,'self vote denied';
 perform public.la_set_poem_reaction(judge,poem,'funny');perform public.la_set_poem_reaction(judge,poem,'funny');
 assert(select funny_count=1 from public.la_poems where id=poem),'repeated funny set is idempotent';
 perform public.la_set_poem_reaction(judge,poem,'like');assert(select funny_count=0 and like_count=1 from public.la_poems where id=poem),'reaction switch';
 perform public.la_set_poem_reaction(judge,poem,null);assert(select funny_count=0 and like_count=0 from public.la_poems where id=poem),'cancel';
 perform public.la_set_poem_reaction(judge,poem,'funny');perform public.la_set_poem_reaction(judge,second_poem,'funny');
 insert into public.la_poem_campaigns(word_id,word,starts_at,writing_ends_at,voting_ends_at) values(w.id,w.word,clock_timestamp()-interval '30 minutes',clock_timestamp()+interval '1 hour',clock_timestamp()+interval '2 hours') returning id into next_campaign;
 perform public.la_submit_poem(author,next_campaign,'검증',array[substring(w.word,1,1)||'첫째',substring(w.word,2,1)||'둘째',substring(w.word,3,1)||'셋째'],gen_random_uuid());
 assert(select count(*)=2 from public.la_poems where author_id=author),'same user can participate next campaign';
 update public.la_poem_campaigns set writing_ends_at=clock_timestamp()-interval '2 minutes',voting_ends_at=clock_timestamp()-interval '1 minute' where id=campaign;
 rejected:=false;
 begin perform public.la_set_poem_reaction(judge,poem,null); exception when others then rejected:=sqlerrm like '%VOTING_CLOSED%'; end;
 assert rejected,'voting deadline';
 current_week:=public.la_poem_maintain_week();assert public.la_poem_maintain_week()=current_week,'weekly job idempotent';
 assert(select jsonb_array_length(final_winners)=2 from public.la_poem_campaigns where id=campaign),'funny count tied final winners';
 assert(select schedule='0 0 * * 1' from cron.job where jobname='la-poem-weekly-maintenance'),'weekly schedule';
end $$;
select 'PASS: one work per user per campaign, idempotent retry, deleted entry limit, next campaign eligibility, exclusive reactions, deadlines, funny leaders, weekly schedule; rolled back' as verification;
